/* ==========================================================================
   Helper Functions & Lookups
   ========================================================================== */

// Helper to look up a tour by id (supports both package and tour params)
function getTourById(id) {
  if (!id) return TOURS_DATA[0];
  const cleanId = id.trim().toLowerCase();
  const found = TOURS_DATA.find(t => t.id.toLowerCase() === cleanId);
  if (found) return found;
  const foundFuzzy = TOURS_DATA.find(t => t.id.toLowerCase().includes(cleanId) || cleanId.includes(t.id.toLowerCase()));
  return foundFuzzy || TOURS_DATA[0];
}

// Get all Manali packages sorted in curated order
function getManaliPackages() {
  const preferredOrder = [
    'manali-bachelors-3d2n',
    'manali-family-3d2n',
    'manali-honeymoon-3d2n',
    'kasol-manali-bachelors-4d3n',
    'kasol-manali-camping-4d3n',
    'manali-family-snow-5d4n',
    'manali-adventure-escape-5d4n',
    'manali-romantic-alpine-5d4n',
    'manali-bachelors-high-pass-4d3n',
    'manali-solang-paragliding-4d3n',
    'manali-riverside-leisure-5d4n',
    'manali-old-cafe-culture-4d3n',
    'manali-rohtang-snow-safari-6d5n',
    'kasol-manali-honeymoon-4d3n',
    'kasol-manali-river-camp-4d3n',
    'shimla-manali-honeymoon-4d3n',
    'shimla-manali-premium-5d4n',
    'shimla-manali-family-5d4n',
    'shimla-kasol-bachelors-4d3n',
    'manali-hampta-pass-trek-5d4n'
  ];
  const list = TOURS_DATA.filter(t => t.destination.toLowerCase() === 'manali');
  return list.sort((a, b) => {
    let ia = preferredOrder.indexOf(a.id);
    let ib = preferredOrder.indexOf(b.id);
    if (ia === -1) ia = 999;
    if (ib === -1) ib = 999;
    return ia - ib;
  });
}

