/* ==========================================================================
   Catalog Rendering & Filtering
   ========================================================================== */
function renderTourCards(tours, targetGridId = 'tours-catalog-grid') {
  const grid = document.getElementById(targetGridId);
  if (!grid) return;

  if (tours.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 60px 20px;">
        <h3 style="font-size: 1.6rem; margin-bottom: 10px;">No matching journeys found</h3>
        <p style="color: var(--text-secondary); margin-bottom: 24px;">Try loosening your filters or talk directly with our travel curator.</p>
        <button class="btn btn-primary" onclick="resetTourFilters()">Reset All Filters</button>
      </div>
    `;
    return;
  }

  grid.innerHTML = tours.map(tour => {
    const isKerala = tour.destination.toLowerCase() === 'kerala';
    const isManali = tour.destination.toLowerCase() === 'manali';
    const badgeText = (tour.categoryBadge || tour.badgeTitle || (tour.category && tour.category[1]) || 'POPULAR').toUpperCase();
    const routeText = tour.routeString || (tour.route ? tour.route.join(' → ') : tour.subtitle || '');
    const tariffLabel = tour.priceFormatted === 'Price on Request' || tour.price === 0 ? 'BROCHURE TARIFF' : 'STARTING FROM';

    return `
      <article class="wf-package-card" data-tour-id="${tour.id}">
        <div class="wf-package-media">
          <img src="${tour.image}" alt="${tour.title} by Crazy Tours" loading="lazy">
          <div class="wf-package-badges">
            <span class="wf-badge-duration">${tour.durationDays}D / ${tour.durationNights}N</span>
            <span class="wf-badge-category">${badgeText}</span>
          </div>
        </div>
        <div class="wf-package-content">
          <div class="wf-package-meta">
            <span class="wf-package-location">📍 ${tour.destination}</span>
            <span class="wf-package-sep">•</span>
            <span class="wf-package-support">${isKerala || isManali || tour.destination.toLowerCase() === 'kashmir' || tour.destination.toLowerCase() === 'goa' ? '24/7 Telugu CC' : 'Handcrafted'}</span>
          </div>
          <h3 class="wf-package-title">${tour.title}</h3>
          <p class="wf-package-route">
            📍 ${routeText}
          </p>
          <p class="wf-package-desc">${tour.description}</p>
          
          <div class="wf-package-chips">
            ${(tour.featureIcons || ['Personal Cab', 'Hotel Stay', 'Breakfast', 'Sightseeing']).slice(0, 5).map(f => {
              let icon = '✓';
              const fl = f.toLowerCase();
              if (fl.includes('cab') || fl.includes('taxi') || fl.includes('car')) icon = '🚗';
              else if (fl.includes('hotel') || fl.includes('stay') || fl.includes('resort')) icon = '🏨';
              else if (fl.includes('breakfast') || fl.includes('meal')) icon = '🍽️';
              else if (fl.includes('sightseeing')) icon = '📷';
              else if (fl.includes('honeymoon')) icon = '🤍';
              else if (fl.includes('shikara') || fl.includes('boat')) icon = '🛶';
              else if (fl.includes('camp')) icon = '⛺';
              return `<span class="wf-chip">${icon} ${f}</span>`;
            }).join('')}
          </div>

          <div class="wf-package-pricing">
            <span class="wf-package-tariff-label">${tariffLabel}</span>
            <div class="wf-package-price-val">${tour.priceFormatted}</div>
          </div>

          <a href="tour-detail.html?package=${tour.id}" class="wf-package-cta">
            <span>View Package</span>
            <span class="wf-package-cta-arrow">→</span>
          </a>
        </div>
      </article>
    `;
  }).join('');
}

function initTourFilters() {
  const categoryPills = document.querySelectorAll('.category-pill');
  const destSelect = document.getElementById('filter-destination');
  const styleSelect = document.getElementById('filter-style');
  const durationSelect = document.getElementById('filter-duration');
  const budgetSelect = document.getElementById('filter-budget');
  const counterEl = document.getElementById('tour-results-counter');
  const searchInput = document.getElementById('kerala-tour-search') || document.getElementById('tour-search-input');

  let activeCategory = 'all';

  function applyFilters() {
    let filtered = [...TOURS_DATA];

    // Search input filtering
    if (searchInput && searchInput.value.trim() !== '') {
      const q = searchInput.value.trim().toLowerCase();
      filtered = filtered.filter(t => {
        const titleMatch = t.title.toLowerCase().includes(q);
        const destMatch = t.destination.toLowerCase().includes(q);
        const routeMatch = t.routeString ? t.routeString.toLowerCase().includes(q) : false;
        const catMatch = t.category ? t.category.some(c => c.toLowerCase().includes(q)) : false;
        const styleMatch = t.style ? t.style.toLowerCase().includes(q) : false;
        const durMatch = (t.duration && t.duration.toLowerCase().includes(q)) || 
                         `${t.durationDays} days`.includes(q) || 
                         `${t.durationDays}d`.includes(q);
        return titleMatch || destMatch || routeMatch || catMatch || styleMatch || durMatch;
      });
    }

    // Category / Tag filter
    if (activeCategory !== 'all') {
      const act = activeCategory.toLowerCase();
      filtered = filtered.filter(t => {
        if (!t.category) return false;
        const matchCat = t.category.some(c => c.toLowerCase() === act || 
          (act === 'bachelor-group' && (c === 'bachelor' || c === 'bachelor-group' || c === 'group'))
        );
        const matchDest = t.destination.toLowerCase() === act;
        const matchRoute = t.route && t.route.some(r => r.toLowerCase().includes(act));
        const matchTitle = t.title.toLowerCase().includes(act);
        return matchCat || matchDest || matchRoute || matchTitle;
      });
    }

    // Destination filter
    if (destSelect && destSelect.value !== 'all') {
      filtered = filtered.filter(t => t.destination.toLowerCase() === destSelect.value.toLowerCase());
    }

    // Style filter
    if (styleSelect && styleSelect.value !== 'all') {
      filtered = filtered.filter(t => t.style && t.style.toLowerCase() === styleSelect.value.toLowerCase());
    }

    // Duration filter
    if (durationSelect && durationSelect.value !== 'all') {
      if (durationSelect.value === 'short') {
        filtered = filtered.filter(t => t.durationDays <= 4);
      } else if (durationSelect.value === 'medium') {
        filtered = filtered.filter(t => t.durationDays >= 5 && t.durationDays <= 6);
      } else if (durationSelect.value === 'long') {
        filtered = filtered.filter(t => t.durationDays > 6);
      }
    }

    // Budget filter
    if (budgetSelect && budgetSelect.value !== 'all') {
      const budgetMax = parseInt(budgetSelect.value, 10);
      filtered = filtered.filter(t => (t.price > 0 ? t.price <= budgetMax : true));
    }

    renderTourCards(filtered);

    if (counterEl) {
      counterEl.textContent = `Showing ${filtered.length} of ${TOURS_DATA.length} Journeys`;
    }
  }

  categoryPills.forEach(pill => {
    pill.addEventListener('click', () => {
      categoryPills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      activeCategory = pill.getAttribute('data-category') || 'all';
      applyFilters();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', applyFilters);
  }

  [destSelect, styleSelect, durationSelect, budgetSelect].forEach(select => {
    if (select) {
      select.addEventListener('change', applyFilters);
    }
  });

  window.resetTourFilters = function() {
    if (destSelect) destSelect.value = 'all';
    if (styleSelect) styleSelect.value = 'all';
    if (durationSelect) durationSelect.value = 'all';
    if (budgetSelect) budgetSelect.value = 'all';
    if (searchInput) searchInput.value = '';
    categoryPills.forEach(p => p.classList.remove('active'));
    if (categoryPills[0]) categoryPills[0].classList.add('active');
    activeCategory = 'all';
    applyFilters();
  };

  // Check URL query parameters for destination pre-selection
  const urlParams = new URLSearchParams(window.location.search);
  const destParam = urlParams.get('dest');
  const catParam = urlParams.get('category') || urlParams.get('filter');
  
  if (destParam && destSelect) {
    destSelect.value = destParam.toLowerCase();
  }
  if (catParam) {
    categoryPills.forEach(p => {
      if (p.getAttribute('data-category') === catParam.toLowerCase()) {
        categoryPills.forEach(x => x.classList.remove('active'));
        p.classList.add('active');
        activeCategory = catParam.toLowerCase();
      }
    });
  }

  // Initial render
  applyFilters();
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.getElementById('tours-catalog-grid')) {
    initTourFilters();
  }
});
